<template><view class="page"><view class="head">{{mode==='handle'?'下级调拨退回处理':'我的调拨退回'}}</view><view class="filters"><view v-for="x in filters" :key="x.value" :class="['filter',status===x.value?'active':'']" @click="change(x.value)">{{x.label}}</view></view><view v-for="item in list" :key="item.id" class="card" @click="detail(item)"><view class="row"><text>{{item.returnNo}}</text><text class="status">{{item.statusText||item.status}}</text></view><text>原调拨：{{item.originalTransferNo}}</text><text>商品：{{item.firstProductName||'--'}} {{item.firstSkuName||''}}</text><text>金额：{{item.returnAmount||0}}</text><text v-if="mode==='handle'">申请人：{{item.applicantName||item.userId}} {{item.applicantPhone||''}}</text></view><view v-if="!list.length" class="empty">暂无退回记录</view></view></template>
<script>import{getJkStockTransferReturnList,getJkHandledReturnList}from'@/api/jk.js';export default{data(){return{mode:'own',status:'',list:[],filters:[{label:'全部',value:''},{label:'待处理',value:'SUBMITTED'},{label:'待寄回',value:'AUDIT_APPROVED'},{label:'待退款',value:'REFUND_PENDING'},{label:'已完成',value:'COMPLETED'}]}},onLoad(q){this.mode=q.mode||'own';this.load()},onShow(){this.load()},methods:{load(){(this.mode==='handle'?getJkHandledReturnList:getJkStockTransferReturnList)({page:1,limit:50,status:this.status}).then(r=>{const p=r.data||r||{};this.list=p.list||[]})},change(s){this.status=s;this.load()},detail(x){uni.navigateTo({url:'/pages/jk/return/detail?mode='+this.mode+'&id='+x.id})}}}</script>
<style scoped>.page{min-height:100vh;background:#f3f8f6;padding:24rpx}.head{padding:20rpx 8rpx;font-size:36rpx;font-weight:700;color:#176d53}.filters{display:flex;flex-wrap:wrap;gap:12rpx;margin-bottom:20rpx}.filter{padding:12rpx 20rpx;border-radius:28rpx;background:#fff;color:#71877f}.filter.active{background:#25bb8e;color:#fff}.card{display:flex;flex-direction:column;gap:10rpx;margin-bottom:18rpx;padding:26rpx;border-radius:20rpx;background:#fff;color:#71877f}.row{display:flex;justify-content:space-between;color:#315b4d;font-weight:650}.status{color:#18a479}.empty{text-align:center;color:#9aaea6;padding:120rpx}</style>
